import math

def branch(r,k):
    if r or k>0:
        p=[math.exp(x)/(math.exp(0)+math.exp(2)) for x in (0,2)]
        if r: next_prob=p[1]
        else: next_prob=None
        if k>0: next_k_tokens=[1,0][:k]; next_k_probs=sorted(p,reverse=True)[:k]
        else: next_k_tokens,next_k_probs=None,None
    return 1,next_k_tokens,next_k_probs,next_prob
for r,k in [(False,0),(True,0),(False,1),(True,1)]:
    try: print(r,k,branch(r,k))
    except Exception as e: print(r,k,type(e).__name__)
p=[1/(1+math.exp(2)),math.exp(2)/(1+math.exp(2))]
